import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { A11yModule, LiveAnnouncer } from '@angular/cdk/a11y';

@Component({
  selector: 'app-modal-panel',
  standalone: true,
  imports: [CommonModule, A11yModule],
  templateUrl: './modal-panel.component.html',
})
export class ModalPanelComponent {
  open = false;

  constructor(private readonly liveAnnouncer: LiveAnnouncer) {}

  show(): void {
    this.open = true;
    this.liveAnnouncer.announce('Confirm action dialog opened', 'assertive');
  }

  close(): void {
    this.open = false;
  }
}
